function biggestOnesBlock(matrix: number[][]): number {
  const m = matrix.length, n = matrix[0].length;
  let best = 0;
  for (let top = 0; top < m; top++) {
    const allOnes = matrix[top].slice();
    for (let bot = top; bot < m; bot++) {
      let width = 0;
      for (let j = 0; j < n; j++) {
        allOnes[j] &= matrix[bot][j];
        width += allOnes[j];
      }
      best = Math.max(best, width * (bot - top + 1));
    }
  }
  return best;
}

