function biggestOnesBlock(matrix: number[][]): number {
  const n = matrix[0].length;
  const h = new Array(n).fill(0);
  let best = 0;
  for (const row of matrix) {
    for (let j = 0; j < n; j++) h[j] = row[j] ? h[j] + 1 : 0;
    const s = h.slice().sort((a, b) => b - a);
    for (let k = 1; k <= n && s[k - 1] > 0; k++) best = Math.max(best, k * s[k - 1]);
  }
  return best;
}

